from collections import Counter, deque

def components(g, color):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==color and not seen[r][c]:
                cells=[]; q=deque([(r,c)]); seen[r][c]=True
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==color and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                comps.append(cells)
    return comps

def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(c for row in g for c in row).most_common(1)[0][0]
    out=[row[:] for row in g]
    colors={c for row in g for c in row}-{bg}
    for color in colors:
        comps=components(g,color)
        if len(comps)<2: continue
        cset=[set(c) for c in comps]
        for i,S in enumerate(cset):
            for j,T in enumerate(cset):
                if i==j: continue
                # find offset aligning S onto T with max overlap
                best=None;bestov=0
                for dr in range(-H+1,H):
                    for dc in range(-W+1,W):
                        ov=sum(1 for (r,c) in S if (r+dr,c+dc) in T)
                        # all S cells must land in-grid
                        if ov>bestov and all(0<=r+dr<H and 0<=c+dc<W for r,c in S):
                            bestov=ov;best=(dr,dc)
                if best and bestov>0:
                    dr,dc=best
                    for (r,c) in S:
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and out[rr][cc]==bg and g[rr][cc]==bg:
                            out[rr][cc]=1
    return out

